            while (!q.empty()) {
                auto [ur, uc] = q.front(); q.pop();
                size++;
                for (int k = 0; k < 4; ++k) {
                    int vr = ur + dr[k], vc = uc + dc[k];
                    if (vr < 0 || vr >= n || vc < 0 || vc >= n) continue;
                    char ch = g[vr][vc];
                    if (ch == 'x') {
                        int nid = idx(vr, vc);
                        if (!visX[nid]) {
                            visX[nid] = 1;
                            q.push({vr, vc});
                        }
                    } else if (ch == '.') {
                        int e = idx(vr, vc);
                        if (mark[e] != gid) {
                            mark[e] = gid;
                            libCount++;
                            lastLib = e;
                        }
                    }
                    // 'o' 忽略
                }
            }

            if (libCount == 1) {
                capture[lastLib] += size;
            }
        }
    }

    vector<tuple<int, int, int>> ans;
    ans.reserve(capture.size());
    for (auto &kv : capture) {
        int e = kv.first, cnt = kv.second;
        int r = e / n, c = e % n;
        ans.push_back({r + 1, c + 1, cnt});
    }
    sort(ans.begin(), ans.end());

    cout << ans.size() << "\n";
    for (auto &t : ans) {
        int a, b, cnt;
        tie(a, b, cnt) = t;
        cout << a << ' ' << b << ' ' << cnt << "\n";
    }
    return 0;
}
